<?php
declare(strict_types=1);
namespace BSPVisual;
require_once dirname(__DIR__,2).'/research/_lib/model.php';
const VERSION='2.1.0'; const ROOT='/visualizations/'; const BASE='https://beyondspacetime.org';
function scenes():array{return [
'photon'=>['title'=>'Journey of a photon','model'=>'foundation:light-slowing','mode'=>'time','question'=>'Does energy loss necessarily imply significant slowing?','description'=>'Watch the conditional fixed-gap packet and the zero-gap reference move along a shared normalized path.','detail'=>'The path length is the trapezoidal integral of returned group-speed samples divided by C times the modeled duration. The path is not an astronomical distance; the marker at its right end is a reference, not a modeled detector.','control'=>['gap'=>0],'sample'=>null,'source_label'=>'Foundation 3 · Review 6.0 Parts XXXIII–XXXIV'],
'clocks'=>['title'=>'Three clocks, one coordinate interval','model'=>'foundation:constant-time','mode'=>'time','question'=>'Can one stipulated clock-rate ratio match all relativistic predictions?','description'=>'Watch reference, candidate and special-relativistic clock counts accumulate on one time axis.','detail'=>'Each revolution represents one count, not a mechanism inside an actual atomic clock. The candidate rate is stipulated; matching a single relative velocity is not independent validation.','control'=>['beta'=>0,'ratio'=>1],'sample'=>null,'source_label'=>'Foundation 2 · Review 6.0 §5.3'],
'separation'=>['title'=>'Separation is not signal speed','model'=>'foundation:separation','mode'=>'sweep','question'=>'How can common-frame separation exceed C without superluminal local signals?','description'=>'Move along the speed-parameter sweep and compare separation rate with relativistic relative speed.','detail'=>'The arrows represent each ship’s speed in the common reference frame, not a trajectory or a signal. The displayed relative speed follows the existing special-relativistic calculation.','control'=>['beta'=>0],'sample'=>'beta','source_label'=>'Foundation 9 · Review 6.0 §3.1–3.3'],
'cosmic-domains'=>['title'=>'Observable reach and hypothetical cosmic domains','model'=>'foundation:cosmic-size','mode'=>'sweep','question'=>'Does an observable reach establish the total size of the cosmos?','description'=>'Compare an illustrative spherical domain with the region accessible to the assumed signal reach.','detail'=>'Nested circles show a central cross-section of the assumed spheres; the accessible fraction is a volume ratio, not an area ratio. This is not wall dynamics, a cosmological horizon calculation or evidence for a neighboring universe.','control'=>['domain'=>4],'sample'=>'domain','source_label'=>'Foundation 10 · book Chapters 26 and 30–32'],
'cosmic-age'=>['title'=>'Age of a reference expansion model','model'=>'foundation:cosmic-age','mode'=>'sweep','question'=>'How do Hubble constant and matter fraction change the modeled age?','description'=>'Compare two flat matter–Λ reference age curves over the same Hubble constant range.','detail'=>'This is a parameter sweep of a flat matter-plus-Λ age formula, neglecting radiation. It is not an animation of cosmic expansion, a fit to measurements, or the age of a hypothetical parent cosmos. The reference matter fraction is an illustrative comparison value.','control'=>['matter'=>.315],'sample'=>'h0','source_label'=>'Foundation 11 · book Chapter 26'],
'escape'=>['title'=>'Coherent conversion and escape','model'=>'evidence:escape','mode'=>'time','question'=>'When does total converted population remain monotone?','description'=>'Observe the incident, local-converted and escaped populations with the reversible zero-escape reference.','detail'=>'The segmented reservoir is a population ledger for the selected-mode solution, not a spatial or individual-photon trajectory. Display geometry clips tiny negative floating-point residuals to zero; raw readouts and exports preserve them.','control'=>['ratio'=>0],'sample'=>null,'source_label'=>'Review 6.0 §15.6 · K11–K13'],
'wall'=>['title'=>'Can a fixed-gap wall be traversed?','model'=>'evidence:wall','mode'=>'sweep','question'=>'Can the two necessary constant-drag requirements overlap?','description'=>'Inspect retention bounds along the ceiling-ratio sweep and the two selected-case drag limits.','detail'=>'The curve is log₁₀ of the maximum retained energy fraction. The two selected-case drag limits are separate from the scrubbed sample. A finite interval is necessary, not proof of a physical wall or a complete traversal solution.','control'=>['loggap'=>-1],'sample'=>'ceiling','source_label'=>'Review 6.0 §10.3–10.4'],
'distance'=>['title'=>'From light attenuation to distance bias','model'=>'foundation:distance-inference','mode'=>'sweep','question'=>'Can an unmodeled attenuation change inferred distance in either direction?','description'=>'Compare calibrated and inferred distance on a shared spatial scale as the attenuation parameter changes.','detail'=>'The two rays represent distance estimates for the same object, not two objects or a change in the actual distance. The signed attenuation experiment is conditional; it does not establish a universal distance correction.','control'=>['extinction'=>0],'sample'=>'extinction','source_label'=>'Foundation 12 · book Chapter 26'],
'anchors'=>['title'=>'Geometric distance anchors','model'=>'evidence:anchors','mode'=>'sweep','question'=>'How large is a proposed shift relative to quoted anchor uncertainties?','description'=>'Compare LMC and NGC 4258 shift-to-uncertainty ratios along a common percentage axis.','detail'=>'The bars are magnitudes relative to the combined quoted uncertainties under unchanged calibration. They are not independent Gaussian detection significances, likelihoods or new measurements.','control'=>['percent'=>0],'sample'=>'percent','source_label'=>'Review 6.0 §14.8']
];}
function solve_scene(string $id,array $p=[]):array{
 $s=scenes()[$id]??throw new \InvalidArgumentException('Unknown visualization.');$model=\BSPResearch\models()[$s['model']];
 $a=$model['kind']==='foundation'?\solve($model['id'],$p):\calc($model['id'],$p);
 $override=$s['control'];if($id==='cosmic-domains')$override=['domain'=>$a['parameters']['reach']];
 $bparams=array_replace($a['parameters'],$override);$b=$model['kind']==='foundation'?\solve($model['id'],$bparams):\calc($model['id'],$bparams);
 $initial=0;if($s['sample']!==null){$min=INF;foreach($a['rows'] as $i=>$row){$d=abs($row[0]-$a['parameters'][$s['sample']]);if($d<$min){$min=$d;$initial=$i;}}}
 $all=array_merge($a['rows'],$b['rows']);$xmin=min(array_column($all,0));$xmax=max(array_column($all,0));$ymin=0.;$ymax=0.;foreach($all as $row)foreach(array_slice($row,1) as $v){$ymin=min($ymin,$v);$ymax=max($ymax,$v);}if($xmax===$xmin)$xmax=$xmin+1;if($ymax===$ymin)$ymax=$ymin+1;
 return ['schema'=>'beyondspacetime.visualization.v1','version'=>VERSION,'scene'=>$id,'mode'=>$s['mode'],'initialSample'=>$initial,'model'=>$s['model'],'candidate'=>$a,'reference'=>$b,'referenceOverrides'=>$override,'sameSweep'=>$a['rows']===$b['rows'],'domain'=>[$xmin,$xmax,$ymin,$ymax],'sourceSolverSha256'=>hash_file('sha256',dirname(__DIR__,2).'/'.($model['kind']==='foundation'?'foundations':'evidence').'/_lib/model.php')];
}
function input(array $q):array{if(count($q)>16)throw new \InvalidArgumentException('Too many parameters.');$p=[];foreach($q as $k=>$v){if(!is_string($k)||!is_string($v)||strlen($v)>64)throw new \InvalidArgumentException('Expected scalar numerical parameters.');$p[$k]=$v;}return $p;}
function catalog():array{$out=[];foreach(scenes() as $id=>$s){$m=\BSPResearch\models()[$s['model']];$out[]=['id'=>$id,'url'=>ROOT.$id.'/','source'=>$m['source']['url'],'modelUrl'=>$m['url'],'params'=>$m['params']]+$s;}return ['schema'=>'beyondspacetime.visualization.catalog.v1','version'=>VERSION,'scenes'=>$out,'api'=>BASE.ROOT.'api/','scope'=>'Original educational diagrams driven by existing foundation and evidence solvers. No new empirical findings.'];}
